// Node.js start-up (loaded by src/instrumentation.ts): on the cPanel host there is no Prisma CLI, so create any missing tables
// from prisma/schema.sql (idempotent CREATE … IF NOT EXISTS, generated by scripts/schema-sql.mjs) before the first request.
// Then, in production, background jobs while the server runs: publish due scheduled posts every minute and a daily database
// backup. The cron routes stay the main trigger (they also wake the app when the host has put it to sleep).
import { mkdir, readFile } from "node:fs/promises";
import path from "node:path";
import { db } from "@/lib/db";

export async function prepareDatabase() {
  const url = process.env.DATABASE_URL;
  if (!url) return;
  try {
    // SQLite creates the file but not its folder (e.g. file:/home/user/gbpninja-data/app.db).
    const file = url.startsWith("file:") ? url.slice(5) : null;
    if (file && path.isAbsolute(file)) await mkdir(path.dirname(file), { recursive: true });
    const sql = await readFile(path.join(process.cwd(), "prisma", "schema.sql"), "utf8");
    const statements = sql
      .split(/;\s*$/m)
      .map((s) => s.replace(/^--.*$/gm, "").trim())
      .filter(Boolean);
    for (const s of statements) db.exec(s);
  } catch (e) {
    console.error("[db] Could not prepare the database:", e);
  }
}

const MINUTE = 60_000;

export function startBackgroundJobs() {
  const g = globalThis as unknown as { __gbpnJobs?: boolean };
  if (g.__gbpnJobs || process.env.NODE_ENV !== "production") return;
  g.__gbpnJobs = true;
  const publish = async () => {
    try {
      const { publishDueSoon } = await import("@/lib/publish-due");
      await publishDueSoon();
    } catch (e) {
      console.error("[jobs] Publishing due posts failed:", e);
    }
  };
  const backup = async () => {
    try {
      const { backupDatabase } = await import("@/lib/backup");
      const file = await backupDatabase();
      if (file) {
        console.log("[jobs] Database backed up to", file);
        const { recordJobRun } = await import("@/lib/job-runs");
        recordJobRun("backup", true, `Saved ${file.split(/[\\/]/).pop()}`);
      }
    } catch (e) {
      console.error("[jobs] Database backup failed:", e);
      const { recordJobRun } = await import("@/lib/job-runs");
      recordJobRun("backup", false, e instanceof Error ? e.message : "Failed");
    }
  };
  setInterval(publish, MINUTE).unref();
  // First backup a minute after start, then checked every hour (one file per day).
  setTimeout(backup, MINUTE).unref();
  setInterval(backup, 60 * MINUTE).unref();
}
